<?php $pageTitle = 'Media'; ?>
<div class="card"><h2>Upload image</h2><p class="muted">JPEG, PNG, WEBP or GIF. Files are stored outside the public web root and served through AfiuCMS.</p><form class="row" method="post" action="/admin/media" enctype="multipart/form-data"><?= csrf_field() ?><input style="max-width:430px" type="file" name="media" accept="image/jpeg,image/png,image/webp,image/gif" required><button class="btn primary" type="submit">Upload</button></form></div><br><div class="media-grid"><?php foreach ($items as $item): ?><div class="media-item"><img src="/media/<?= (int) $item['id'] ?>" alt=""><div class="media-meta"><strong><?= e($item['original_name']) ?></strong><div class="muted"><?= e($item['mime_type']) ?> · <?= number_format(((int)$item['size_bytes'])/1024, 1) ?> KB</div><br><form method="post" action="/admin/media/<?= (int) $item['id'] ?>/delete" onsubmit="return confirm('Delete this file?')"><?= csrf_field() ?><button class="btn small danger" type="submit">Delete</button></form></div></div><?php endforeach; ?><?php if (!$items): ?><p class="muted">No media uploaded yet.</p><?php endif; ?></div>
